/**
 * Teams a person can pick to color the app: college football for now,
 * from ESPN (cfb-teams.json, regenerated by scripts/cfb-teams.ts). A
 * user stores only the key ("cfb:251"); colors and logo are looked up
 * here, so a refreshed file recolors everyone without a migration.
 *
 * When SportsArc's own teams exist they bring their colors with them and
 * this list stays for fans of a college team.
 */

import { readFileSync } from "node:fs";

export interface PublicTeam {
  key: string;
  /** "Texas Longhorns" */
  name: string;
  /** "Texas": how Gemini names the team in a market. */
  school: string;
  abbr: string;
  /** #rrggbb */
  color: string;
  alt: string | null;
  logo: string | null;
}

const FILE = new URL("./cfb-teams.json", import.meta.url);
const TEAMS: PublicTeam[] = (JSON.parse(readFileSync(FILE, "utf8")).teams as (PublicTeam & { mascot?: string })[])
  .map(({ key, name, school, abbr, color, alt, logo }) => ({ key, name, school, abbr, color, alt, logo }));
const BY_KEY = new Map(TEAMS.map((t) => [t.key, t]));

/** Shown before anyone types: Texas first, then the usual top programs. */
const FEATURED_KEYS = ["251", "130", "194", "2483", "333", "61", "99", "30", "87", "213"].map((id) => `cfb:${id}`);
const FEATURED = FEATURED_KEYS.map((k) => BY_KEY.get(k)).filter((t): t is PublicTeam => Boolean(t));

export const teamByKey = (key: unknown): PublicTeam | null =>
  typeof key === "string" ? BY_KEY.get(key) ?? null : null;

const fold = (s: string): string => s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "");

/**
 * Teams matching a search: an exact abbreviation or school first, then
 * names starting with it, then names containing it. No query: featured.
 */
export function searchTeams(q: string, limit = 20): PublicTeam[] {
  const needle = fold(q.trim());
  if (!needle) return FEATURED;
  const scored: [number, PublicTeam][] = [];
  for (const t of TEAMS) {
    const name = fold(t.name);
    const school = fold(t.school);
    let score = -1;
    if (fold(t.abbr) === needle || school === needle) score = 0;
    else if (name.startsWith(needle) || school.startsWith(needle)) score = 1;
    else if (name.includes(needle)) score = 2;
    if (score >= 0) scored.push([score, t]);
  }
  return scored.sort((a, b) => a[0] - b[0] || a[1].name.localeCompare(b[1].name)).slice(0, limit).map(([, t]) => t);
}
